//! An ordered sequence stored as a list of sorted sublists.
//!
//! A single flat `Vec` would make every insertion shift the whole tail; a
//! balanced tree would cost a node allocation and a cache miss per element.
//! Splitting the sequence into bounded sublists keeps the best of both: picking
//! the sublist is a binary search over the sublist maxima, and inserting inside
//! it only memmoves at most `2 * load` contiguous elements.

use std::cmp::Ordering;
use std::iter::FromIterator;

/// Elements a sublist may hold before it is split in half.
const DEFAULT_LOAD: usize = 1000;

/// A sequence that always yields its elements in ascending order.
///
/// Duplicates are allowed and are kept adjacent; see [`SortedSet`] for the
/// de-duplicating variant.
///
/// [`SortedSet`]: crate::sortedcontainers::SortedSet
#[derive(Clone, Debug)]
pub struct SortedList<T: Ord> {
    /// Sorted sublists whose concatenation is the whole sequence, in order.
    /// Every sublist is non-empty, so `last().unwrap()` never panics.
    lists: Vec<Vec<T>>,
    len: usize,
    load: usize,
}

impl<T: Ord> SortedList<T> {
    /// Creates an empty list with the default load factor.
    pub fn new() -> Self {
        Self::with_load(DEFAULT_LOAD)
    }

    /// Creates an empty list whose sublists hold up to `load` elements.
    ///
    /// # Panics
    ///
    /// Panics if `load` is zero, since a sublist must be able to hold an element.
    pub fn with_load(load: usize) -> Self {
        assert!(load > 0, "load factor must be positive");
        Self { lists: Vec::new(), len: 0, load }
    }

    /// Number of elements in the list.
    pub fn len(&self) -> usize {
        self.len
    }

    /// Returns `true` when the list holds no elements.
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Removes every element, keeping the load factor.
    pub fn clear(&mut self) {
        self.lists.clear();
        self.len = 0;
    }

    /// Inserts `value`, keeping the sequence sorted.
    ///
    /// Equal elements are inserted after the ones already present, so inserting
    /// a run of equal values preserves their insertion order.
    pub fn insert(&mut self, value: T) {
        if self.lists.is_empty() {
            self.lists.push(vec![value]);
            self.len = 1;
            return;
        }

        // Bisect right over the sublist maxima: the first sublist whose largest
        // element is greater than `value` is the one that must absorb it.
        let mut pos = self.lists.partition_point(|sub| sub.last().unwrap() <= &value);
        if pos == self.lists.len() {
            // `value` is a new maximum, so it extends the final sublist.
            pos -= 1;
            self.lists[pos].push(value);
        } else {
            let sub = &mut self.lists[pos];
            let idx = sub.partition_point(|other| other <= &value);
            sub.insert(idx, value);
        }

        self.len += 1;
        self.split_if_oversized(pos);
    }

    /// Returns `true` when `value` is present.
    pub fn contains(&self, value: &T) -> bool {
        self.locate(value).is_some()
    }

    /// Removes one occurrence of `value`, returning whether anything was removed.
    pub fn remove(&mut self, value: &T) -> bool {
        match self.locate(value) {
            Some((pos, idx)) => {
                self.delete(pos, idx);
                true
            }
            None => false,
        }
    }

    /// Returns the element at `idx` in sorted order, or `None` when out of range.
    ///
    /// Costs one step per sublist, i.e. `O(len / load)`.
    pub fn get(&self, idx: usize) -> Option<&T> {
        if idx >= self.len {
            return None;
        }
        let mut remaining = idx;
        for sub in &self.lists {
            if remaining < sub.len() {
                return Some(&sub[remaining]);
            }
            remaining -= sub.len();
        }
        None
    }

    /// Returns the smallest element.
    pub fn first(&self) -> Option<&T> {
        self.lists.first().map(|sub| &sub[0])
    }

    /// Returns the largest element.
    pub fn last(&self) -> Option<&T> {
        self.lists.last().map(|sub| sub.last().unwrap())
    }

    /// Number of elements strictly less than `value`.
    ///
    /// This is also the position at which `value` would be inserted first.
    pub fn rank(&self, value: &T) -> usize {
        let pos = self.lists.partition_point(|sub| sub.last().unwrap() < value);
        let before: usize = self.lists[..pos].iter().map(Vec::len).sum();
        match self.lists.get(pos) {
            Some(sub) => before + sub.partition_point(|other| other < value),
            None => before,
        }
    }

    /// Iterates over the elements in ascending order.
    pub fn iter(&self) -> impl Iterator<Item = &T> {
        self.lists.iter().flatten()
    }

    /// Builds a list from values that are already sorted ascending.
    ///
    /// Chunking straight into sublists is `O(n)`, where inserting one by one
    /// would pay a binary search and a memmove per element.
    pub fn from_sorted(values: Vec<T>) -> Self {
        Self::from_sorted_with_load(values, DEFAULT_LOAD)
    }

    /// [`from_sorted`](Self::from_sorted) with an explicit load factor.
    pub fn from_sorted_with_load(values: Vec<T>, load: usize) -> Self {
        assert!(load > 0, "load factor must be positive");
        let len = values.len();
        let mut lists: Vec<Vec<T>> = Vec::with_capacity(len / load + 1);
        let mut chunk: Vec<T> = Vec::with_capacity(load.min(len));

        for value in values {
            chunk.push(value);
            if chunk.len() == load {
                let next = Vec::with_capacity(load);
                lists.push(std::mem::replace(&mut chunk, next));
            }
        }
        if !chunk.is_empty() {
            lists.push(chunk);
        }

        Self { lists, len, load }
    }

    /// Finds the sublist and offset of the first occurrence of `value`.
    fn locate(&self, value: &T) -> Option<(usize, usize)> {
        // Bisect left over the maxima: any occurrence of `value` lives in the
        // first sublist whose largest element is at least `value`.
        let pos = self.lists.partition_point(|sub| sub.last().unwrap() < value);
        let sub = self.lists.get(pos)?;
        let idx = sub.partition_point(|other| other < value);
        match sub.get(idx) {
            Some(found) if found == value => Some((pos, idx)),
            _ => None,
        }
    }

    /// Removes `lists[pos][idx]` and restores the sublist size invariants.
    fn delete(&mut self, pos: usize, idx: usize) {
        self.lists[pos].remove(idx);
        self.len -= 1;

        if self.lists[pos].is_empty() {
            self.lists.remove(pos);
        } else if self.lists.len() > 1 && self.lists[pos].len() <= self.load / 2 {
            // Fold the undersized sublist into a neighbour so the sublist count
            // stays proportional to `len / load` under repeated removals.
            let target = pos.saturating_sub(1);
            let donor = self.lists.remove(target + 1);
            self.lists[target].extend(donor);
            self.split_if_oversized(target);
        }
    }

    /// Splits `lists[pos]` in two if it has grown past twice the load factor.
    fn split_if_oversized(&mut self, pos: usize) {
        if self.lists[pos].len() > self.load * 2 {
            let half = self.lists[pos].split_off(self.load);
            self.lists.insert(pos + 1, half);
        }
    }
}

impl<T: Ord> Default for SortedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T: Ord> FromIterator<T> for SortedList<T> {
    fn from_iter<I: IntoIterator<Item = T>>(iter: I) -> Self {
        let mut values: Vec<T> = iter.into_iter().collect();
        values.sort();
        Self::from_sorted(values)
    }
}

impl<T: Ord> Extend<T> for SortedList<T> {
    fn extend<I: IntoIterator<Item = T>>(&mut self, iter: I) {
        for value in iter {
            self.insert(value);
        }
    }
}

impl<T: Ord> PartialEq for SortedList<T> {
    fn eq(&self, other: &Self) -> bool {
        self.len == other.len && self.iter().eq(other.iter())
    }
}

impl<T: Ord> Eq for SortedList<T> {}

impl<T: Ord> PartialOrd for SortedList<T> {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl<T: Ord> Ord for SortedList<T> {
    fn cmp(&self, other: &Self) -> Ordering {
        self.iter().cmp(other.iter())
    }
}

#[cfg(test)]
mod tests {
    use super::SortedList;

    /// Small load factor so the split/merge paths run on tiny inputs.
    fn list_of(values: &[i32]) -> SortedList<i32> {
        let mut list = SortedList::with_load(2);
        for &value in values {
            list.insert(value);
        }
        list
    }

    fn collect(list: &SortedList<i32>) -> Vec<i32> {
        list.iter().copied().collect()
    }

    #[test]
    fn insert_keeps_elements_sorted_across_splits() {
        let list = list_of(&[5, 1, 9, 3, 7, 0, 8, 2, 6, 4]);
        assert_eq!(collect(&list), (0..10).collect::<Vec<_>>());
        assert_eq!(list.len(), 10);
    }

    #[test]
    fn insert_keeps_duplicates() {
        let list = list_of(&[2, 1, 2, 1, 2]);
        assert_eq!(collect(&list), vec![1, 1, 2, 2, 2]);
    }

    #[test]
    fn contains_reports_membership() {
        let list = list_of(&[10, 20, 30, 40, 50]);
        assert!(list.contains(&10));
        assert!(list.contains(&50));
        assert!(!list.contains(&35));
        assert!(!list.contains(&0));
        assert!(!list.contains(&60));
        assert!(!SortedList::<i32>::new().contains(&1));
    }

    #[test]
    fn remove_drops_one_occurrence_and_merges_sublists() {
        let mut list = list_of(&[1, 2, 2, 3, 4, 5, 6]);
        assert!(list.remove(&2));
        assert_eq!(collect(&list), vec![1, 2, 3, 4, 5, 6]);
        assert!(!list.remove(&99));
        for value in [1, 3, 5] {
            assert!(list.remove(&value));
        }
        assert_eq!(collect(&list), vec![2, 4, 6]);
        for value in [2, 4, 6] {
            assert!(list.remove(&value));
        }
        assert!(list.is_empty());
        assert_eq!(collect(&list), Vec::<i32>::new());
    }

    #[test]
    fn get_and_bounds_follow_sorted_order() {
        let list = list_of(&[30, 10, 20]);
        assert_eq!(list.get(0), Some(&10));
        assert_eq!(list.get(2), Some(&30));
        assert_eq!(list.get(3), None);
        assert_eq!(list.first(), Some(&10));
        assert_eq!(list.last(), Some(&30));
        assert_eq!(SortedList::<i32>::new().first(), None);
    }

    #[test]
    fn rank_counts_smaller_elements() {
        let list = list_of(&[1, 3, 3, 5]);
        assert_eq!(list.rank(&0), 0);
        assert_eq!(list.rank(&3), 1);
        assert_eq!(list.rank(&4), 3);
        assert_eq!(list.rank(&9), 4);
    }

    #[test]
    fn from_sorted_matches_repeated_insertion() {
        let values: Vec<i32> = (0..50).collect();
        let bulk = SortedList::from_sorted_with_load(values.clone(), 2);
        let mut incremental = SortedList::with_load(2);
        for value in values.iter().rev() {
            incremental.insert(*value);
        }
        assert_eq!(bulk, incremental);
        assert_eq!(bulk.len(), 50);
        assert_eq!(collect(&bulk), values);
    }

    #[test]
    fn from_iter_sorts_arbitrary_input() {
        let list: SortedList<i32> = vec![4, 1, 3, 1].into_iter().collect();
        assert_eq!(collect(&list), vec![1, 1, 3, 4]);
    }
}

