use std::cmp::Ordering;
use std::iter::FromIterator;

use super::sorted_list::SortedList;

/// A set that always yields its elements in ascending order.
#[derive(Clone, Debug, Default, PartialEq, Eq, PartialOrd, Ord)]
pub struct SortedSet<T: Ord> {
    elements: SortedList<T>,
}

impl<T: Ord> SortedSet<T> {
    /// Creates an empty set.
    pub fn new() -> Self {
        Self { elements: SortedList::new() }
    }

    /// Inserts `value`, returning `true` when it was not already present.
    pub fn insert(&mut self, value: T) -> bool {
        if self.elements.contains(&value) {
            return false;
        }
        self.elements.insert(value);
        true
    }

    /// Returns `true` when `value` is a member of the set.
    pub fn contains(&self, value: &T) -> bool {
        self.elements.contains(value)
    }

    /// Number of elements in the set.
    pub fn size(&self) -> usize {
        self.elements.len()
    }

    /// Number of elements in the set; alias of [`size`](Self::size).
    pub fn len(&self) -> usize {
        self.elements.len()
    }

    /// Returns `true` when the set is empty.
    pub fn is_empty(&self) -> bool {
        self.elements.is_empty()
    }

    /// Removes `value`, returning whether it was present.
    pub fn remove(&mut self, value: &T) -> bool {
        self.elements.remove(value)
    }

    /// Removes every element.
    pub fn clear(&mut self) {
        self.elements.clear();
    }

    /// Returns the element at `idx` in sorted order.
    pub fn get(&self, idx: usize) -> Option<&T> {
        self.elements.get(idx)
    }

    /// Returns the smallest element.
    pub fn first(&self) -> Option<&T> {
        self.elements.first()
    }

    /// Returns the largest element.
    pub fn last(&self) -> Option<&T> {
        self.elements.last()
    }

    /// Number of elements strictly less than `value`.
    pub fn rank(&self, value: &T) -> usize {
        self.elements.rank(value)
    }

    /// Iterates over the elements in ascending order.
    pub fn iter(&self) -> impl Iterator<Item = &T> {
        self.elements.iter()
    }

    /// Returns `true` when every element of `self` is also in `other`.
    pub fn is_subset_of(&self, other: &Self) -> bool {
        self.size() <= other.size() && self.iter().all(|value| other.contains(value))
    }

    /// Returns `true` when the two sets share no element.
    pub fn is_disjoint_from(&self, other: &Self) -> bool {
        let (small, large) =
            if self.size() <= other.size() { (self, other) } else { (other, self) };
        small.iter().all(|value| !large.contains(value))
    }
}

impl<T: Ord + Clone> SortedSet<T> {
    /// Returns the elements present in either set.
    pub fn union_with(&self, other: &Self) -> Self {
        self.merge(other, true, true, true)
    }

    /// Returns the elements present in both sets.
    pub fn intersection_with(&self, other: &Self) -> Self {
        self.merge(other, false, true, false)
    }

    /// Returns the elements of `self` that are not in `other`.
    pub fn difference_with(&self, other: &Self) -> Self {
        self.merge(other, true, false, false)
    }

    /// Returns the elements present in exactly one of the two sets.
    pub fn symmetric_difference_with(&self, other: &Self) -> Self {
        self.merge(other, true, false, true)
    }

    /// Walks both sorted sequences once, keeping the elements selected by the
    /// three flags: those unique to `self`, those common to both, and those
    /// unique to `other`. The result is produced in order, so it can be built
    /// in bulk rather than one insertion at a time.
    fn merge(&self, other: &Self, keep_left: bool, keep_both: bool, keep_right: bool) -> Self {
        let mut merged = Vec::with_capacity(self.size() + other.size());
        let mut left = self.iter().peekable();
        let mut right = other.iter().peekable();

        loop {
            let order = match (left.peek(), right.peek()) {
                (Some(a), Some(b)) => a.cmp(b),
                (Some(_), None) => Ordering::Less,
                (None, Some(_)) => Ordering::Greater,
                (None, None) => break,
            };
            match order {
                Ordering::Less => {
                    let value = left.next().unwrap();
                    if keep_left {
                        merged.push(value.clone());
                    }
                }
                Ordering::Greater => {
                    let value = right.next().unwrap();
                    if keep_right {
                        merged.push(value.clone());
                    }
                }
                Ordering::Equal => {
                    let value = left.next().unwrap();
                    right.next();
                    if keep_both {
                        merged.push(value.clone());
                    }
                }
            }
        }

        Self { elements: SortedList::from_sorted(merged) }
    }
}

impl<T: Ord> FromIterator<T> for SortedSet<T> {
    fn from_iter<I: IntoIterator<Item = T>>(iter: I) -> Self {
        let mut set = Self::new();
        set.extend(iter);
        set
    }
}

impl<T: Ord> Extend<T> for SortedSet<T> {
    fn extend<I: IntoIterator<Item = T>>(&mut self, iter: I) {
        for value in iter {
            self.insert(value);
        }
    }
}

