    let mut i = 0;

    // C's `isspace` in the default locale, which includes the vertical tab that
    // `u8::is_ascii_whitespace` leaves out.
    while i < bytes.len() && (bytes[i].is_ascii_whitespace() || bytes[i] == b'\x0b') {
        i += 1;
    }

    let negative = match bytes.get(i) {
        Some(&sign @ (b'+' | b'-')) => {
            i += 1;
            sign == b'-'
        }
        _ => false,
    };

    let mut magnitude: i64 = 0;
    let mut saturated = false;
    while let Some(digit) = bytes.get(i).and_then(|byte| (*byte as char).to_digit(10)) {
        if !saturated {
            match magnitude.checked_mul(10).and_then(|acc| acc.checked_add(digit as i64)) {
                Some(acc) => magnitude = acc,
                None => saturated = true,
            }
        }
        i += 1;
    }

    let value = match (saturated, negative) {
        (true, false) => i64::MAX,
        (true, true) => i64::MIN,
        (false, true) => -magnitude,
        (false, false) => magnitude,
    };
    value as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut n: i32 = 6;
    if args.len() > 1 {
        n = atoi(&args[1]);
    }

    let mut s1: SortedSet<i32> = SortedSet::new();
    let mut s2: SortedSet<i32> = SortedSet::new();
    for i in 0..n {
        s1.insert(i);
        // `wrapping_mul` mirrors what the C++ build does on signed overflow,
        // which only comes into play for absurdly large `n`.
        s2.insert(i.wrapping_mul(2));
    }

    let s3 = s1.union_with(&s2);

    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());

    writeln!(out, "{}", s1.size()).unwrap();
    writeln!(out, "{}", s2.size()).unwrap();
    writeln!(out, "{}", s3.size()).unwrap();

    for i in 0..n {
        // `std::cout` prints a bool as 1 or 0 unless `boolalpha` is set.
        write!(out, "{} ", u8::from(s3.contains(&i))).unwrap();
    }
    writeln!(out).unwrap();
}

#[cfg(test)]
mod tests {
    use super::atoi;

    #[test]
    fn atoi_matches_c_semantics() {
        assert_eq!(atoi("6"), 6);
        assert_eq!(atoi("  7  "), 7);
        assert_eq!(atoi("\t\n\x0b\x0c\r8"), 8);
        assert_eq!(atoi("+4"), 4);
        assert_eq!(atoi("-3"), -3);
        assert_eq!(atoi("12xy"), 12);
        assert_eq!(atoi("abc"), 0);
        assert_eq!(atoi(""), 0);
        assert_eq!(atoi("- 5"), 0);
        assert_eq!(atoi("2147483647"), i32::MAX);
    }

    #[test]
    fn atoi_truncates_out_of_range_values_like_glibc() {
        assert_eq!(atoi("2147483648"), i32::MIN);
        assert_eq!(atoi("4294967301"), 5);
        // Beyond `long`, `strtol` saturates to LONG_MAX/LONG_MIN first.
        assert_eq!(atoi("99999999999999999999999"), i64::MAX as i32);
        assert_eq!(atoi("-99999999999999999999999"), i64::MIN as i32);
    }
}

